  let connection;
  try {
    connection = typeof scope?.get === "function" ? scope.get("connection") : undefined;
  } catch {
    connection = undefined;
  }
  if (connection === undefined || typeof connection.requestRejection !== "function") {
    return {
      allowed: false,
      status: 503,
      error:
        "本机没有可用的 `connection` 服务（宿主请求授权上下文缺失），" +
