        "插件本体（台账 / 压缩 / 日志）不受影响。",
    };
  }
  let rejection;
  try {
    rejection = connection.requestRejection(req);
  } catch (e) {
    return {
      allowed: false,
      status: 403,
      error: `请求授权检查失败，已拒绝：${String((e && e.message) || e)}`,
